mapper.update:
UPDATE shop_search_sync_task
SET status=1,
    locked_at=#{now},
    updated_at=CURRENT_TIMESTAMP
WHERE shop_id=#{shopId}
  AND version=#{version}
  AND (
      (status=0 AND next_retry_at<=#{now})
      OR (status=1 AND (locked_at IS NULL OR locked_at<=#{staleBefore}))
  )

